export function getCurrentUserId(){return localStorage.getItem("currentUserId")||localStorage.setItem("currentUserId","user-1"),localStorage.getItem("currentUserId")}export async function getAllPosts(){const t=localStorage.getItem("my_posts");if(t)return JSON.parse(t);try{const t=await fetch("./data/posts.json");if(!t.ok)throw new Error("Gönderiler yüklenirken hata oluştu.");const e=await t.json();return localStorage.setItem("my_posts",JSON.stringify(e)),e}catch(t){return console.error("postService Hata:",t),[]}}export async function getPostById(t){return(await getAllPosts()).find(e=>String(e.postId)===String(t))}export async function getPostsByUserId(t){return(await getAllPosts()).filter(e=>String(e.userId)===String(t))}export async function getMyPosts(){const t=getCurrentUserId();return await getPostsByUserId(t)}export async function createNewPost(t){const e=await getAllPosts(),n=getCurrentUserId(),r={postId:"post-"+Date.now(),userId:n,imageUrl:t.image||"images/görsel.jpeg",createdAt:(new Date).toISOString(),commentCount:0,products:[{category:t.tagCategory,brand:t.brand,link:t.productLink||"#"}],comments:[],dupes:[]};return e.unshift(r),localStorage.setItem("my_posts",JSON.stringify(e)),r}export async function addCommentToPost(t,e){const n=await getAllPosts(),r=n.findIndex(e=>String(e.postId)===String(t));if(-1!==r){const t={user:"damlaaltunn",avatar:"images/profiller-img.png",text:e};return n[r].comments||(n[r].comments=[]),n[r].comments.push(t),n[r].commentCount=(n[r].commentCount||0)+1,localStorage.setItem("my_posts",JSON.stringify(n)),{updatedPost:n[r],newComment:t}}return null}export async function deleteCommentFromPost(t,e){const n=await getAllPosts(),r=n.findIndex(e=>String(e.postId)===String(t));return-1!==r&&n[r].comments?(n[r].comments.splice(e,1),n[r].commentCount=Math.max(0,(n[r].commentCount||1)-1),localStorage.setItem("my_posts",JSON.stringify(n)),n[r]):null}export async function addDupeToPost(t,e){const n=await getAllPosts(),r=n.findIndex(e=>String(e.postId)===String(t));if(-1!==r){n[r].dupes||(n[r].dupes=[]);const t={user:"damlaaltunn",avatar:"images/profiller-img.png",items:[{category:e.category,brand:e.brand,link:e.link||"#",image:e.image||null}]};return n[r].dupes.push(t),localStorage.setItem("my_posts",JSON.stringify(n)),n[r]}return null}